}

function isLicaLabel(s) {
  var n = norm(s);
  return n === 'позиција' || n === 'функција' || n === 'вид'
    || n === 'сопственички удел' || n === 'удел'
    || n === 'од' || n === 'до' || n === 'име' || n === 'име и презиме';
}

