    var limit = Math.min(L.length, i + 1 + LICA_WINDOW);
    var j = i + 1;

    // First non-label line after the anchor is the name.
    while (j < limit && !isAnchor(j) && isLicaLabel(L[j])) j++;
    if (j < limit && !isAnchor(j)) { rec.name = L[j]; j++; }

    for (; j < limit && !isAnchor(j); j++) {
