    var pm = rec.name.match(/\(\s*(\d{1,3}(?:[.,]\d{1,4})?)\s*%\s*\)/);
    if (pm) {
      if (!rec.share) rec.share = pm[1] + '%';
      rec.name = rec.name.replace(pm[0], '').replace(/\s{2,}/g, ' ').trim();
    }
    if (rec.share && !/%/.test(rec.share)) rec.share = rec.share.trim() + '%';

